window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6abf7ba4a479d08a"]={"versions": [{"id": "FIG-6abf7ba4a479d08a", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm Service Discovery Eventgroup Pub/Sub (Unicast)</code>) im Kontext des AUTOSAR SOME/IP Service Discovery Protocols (SOME/IP-SD). Es modelliert das serverseitige Verhalten und den Lebenszyklus des Publish/Subscribe-Mechanismus für Unicast-Eventgroups (<code>Eventgroup_PubSub (Unicast Eventgroup)</code>) in Abhängigkeit vom übergeordneten Verfügbarkeitszustand des Services.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände / Composite States:</strong>\n<ul class=\"fig-list\"><li><code>Eventgroup_PubSub (Unicast Eventgroup)</code>: Haupt-Zustandsautomat mit Initialknoten.\n</li><li><code>Service Down</code>: Einfacher Zustand bei inaktivem bzw. nicht verfügbarem Service.\n</li><li><code>Service Up</code>: Zusammengesetzter Zustand (Composite State) mit eigenem Sub-Initialknoten und den Subzuständen <code>Not Subscribed</code> sowie <code>Subscribed</code>.\n</li></ul>\n</li><li><strong>Nachrichten &amp; Schnittstellen (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Empfangene Nachrichten: <code>SubscribeEventgroup</code>, <code>StopSubscribeEventgroup</code>.\n</li><li>Gesendete Nachrichten: <code>SubscribeEventgroupAck</code>.\n</li></ul>\n</li><li><strong>Interne Aktionen &amp; Routing-Steuerung:</strong>\n<ul class=\"fig-list\"><li><code>enableEvents()</code> (in AUTOSAR abgebildet auf <code>enableTxRoutingGroup</code>).\n</li><li><code>disableEvents()</code> (in AUTOSAR abgebildet auf <code>disableTxRoutingGroup</code>).\n</li></ul>\n</li><li><strong>Bedingungen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li>Guards: <code>[Service==Down]</code>, <code>[Service==Up]</code>, <code>[SubscriptionCounter==1]</code>.\n</li><li>Timer-Ereignis: <code>TTL_expired</code>.\n</li></ul>\n</li><li><strong>Kommentare / Notizen:</strong>\n<ul class=\"fig-list\"><li>Hinweis: „OfferService is implicit PublishEventgroup“.\n</li><li>Mapping-Notiz: „AUTOSAR: enableEvents = enableTxRoutingGroup, disableEvents = disableTxRoutingGroup“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Service-Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Vom initialen Pseudozustand erfolgt je nach Guard-Bedingung der Übergang nach <code>Service Down</code> (<code>[Service==Down]</code>) oder direkt in den Composite State <code>Service Up</code> (<code>[Service==Up]</code>).\n</li><li>Zwischen <code>Service Down</code> und <code>Service Up</code> schalten die Events <code>ServiceUp</code> bzw. <code>ServiceDown</code> um.\n</li></ul>\n</li><li><strong>Ablauf innerhalb von Service Up:</strong>\n<ul class=\"fig-list\"><li>Eintritt über den Sub-Initialknoten in <code>Not Subscribed</code>.\n</li><li><code>Not Subscribed</code> -&gt; <code>Subscribed</code>: Bei <code>receive(SubscribeEventgroup)</code> wird <code>/enableEvents()</code> ausgeführt und <code>send(SubscribeEventgroupAck)</code> ausgelöst.\n</li><li>Selbstübergang an <code>Subscribed</code>: Bei erneutem <code>receive(SubscribeEventgroup)</code> (Erneuerung/weitere Subskription) erfolgt <code>/send(SubscribeEventgroupAck)</code>.\n</li><li><code>Subscribed</code> -&gt; <code>Not Subscribed</code>:\n<ul class=\"fig-list\"><li>Explizite Abmeldung über <code>receive(StopSubscribeEventgroup)</code> mit Aktion <code>/disableEvents()</code>.\n</li><li>Timeout-Ablauf über <code>TTL_expired</code> mit Guard <code>[SubscriptionCounter==1]</code> und Aktion <code>/disableEvents()</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindliches Zustandsdiagramm für SOME/IP-SD-Serverimplementierungen gemäß Spezifikationsanforderung (z. B. PRS_SOMEIPSD_00466).\n</li><li>Definiert das exakte Zusammenspiel zwischen Empfang von SD-Subskriptionsnachrichten, dem Senden positiver Quittungen (<code>SubscribeEventgroupAck</code>) und dem Schalten der Event-Übertragung.\n</li><li>Das BSW-Modul (z. B. <code>SoAd</code> / <code>Sd</code>) muss sicherstellen, dass bei der ersten Subskription das Event-Routing aktiviert (<code>enableTxRoutingGroup</code>) und bei Wegfall des letzten Abonnenten (<code>SubscriptionCounter==1</code> oder <code>StopSubscribeEventgroup</code>) deaktiviert wird (<code>disableTxRoutingGroup</code>).\n</li><li>Das Bereitstellen des Dienstes (<code>OfferService</code>) impliziert automatisch die Publikationsbereitschaft der zugehörigen Eventgroups (<code>PublishEventgroup</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-641dbb8d7d0c16ee", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm Service Discovery Eventgroup Pub/Sub (Unicast)</code>) im Kontext des AUTOSAR SOME/IP Service Discovery Protocols (SOME/IP-SD). Es modelliert das serverseitige Verhalten und den Lebenszyklus des Publish/Subscribe-Mechanismus für Unicast-Eventgroups (<code>Eventgroup_PubSub (Unicast Eventgroup)</code>) in Abhängigkeit vom übergeordneten Verfügbarkeitszustand des Services.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände / Composite States:</strong>\n<ul class=\"fig-list\"><li><code>Eventgroup_PubSub (Unicast Eventgroup)</code>: Haupt-Zustandsautomat mit Initialknoten.\n</li><li><code>Service Down</code>: Einfacher Zustand bei inaktivem bzw. nicht verfügbarem Service.\n</li><li><code>Service Up</code>: Zusammengesetzter Zustand (Composite State) mit eigenem Sub-Initialknoten und den Subzuständen <code>Not Subscribed</code> sowie <code>Subscribed</code>.\n</li></ul>\n</li><li><strong>Nachrichten &amp; Schnittstellen (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Empfangene Nachrichten: <code>SubscribeEventgroup</code>, <code>StopSubscribeEventgroup</code>.\n</li><li>Gesendete Nachrichten: <code>SubscribeEventgroupAck</code>.\n</li></ul>\n</li><li><strong>Interne Aktionen &amp; Routing-Steuerung:</strong>\n<ul class=\"fig-list\"><li><code>enableEvents()</code> (in AUTOSAR abgebildet auf <code>enableTxRoutingGroup</code>).\n</li><li><code>disableEvents()</code> (in AUTOSAR abgebildet auf <code>disableTxRoutingGroup</code>).\n</li></ul>\n</li><li><strong>Bedingungen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li>Guards: <code>[Service==Down]</code>, <code>[Service==Up]</code>, <code>[SubscriptionCounter==1]</code>.\n</li><li>Timer-Ereignis: <code>TTL_expired</code>.\n</li></ul>\n</li><li><strong>Kommentare / Notizen:</strong>\n<ul class=\"fig-list\"><li>Hinweis: „OfferService is implicit PublishEventgroup“.\n</li><li>Mapping-Notiz: „AUTOSAR: enableEvents = enableTxRoutingGroup, disableEvents = disableTxRoutingGroup“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Service-Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Vom initialen Pseudozustand erfolgt je nach Guard-Bedingung der Übergang nach <code>Service Down</code> (<code>[Service==Down]</code>) oder direkt in den Composite State <code>Service Up</code> (<code>[Service==Up]</code>).\n</li><li>Zwischen <code>Service Down</code> und <code>Service Up</code> schalten die Events <code>ServiceUp</code> bzw. <code>ServiceDown</code> um.\n</li></ul>\n</li><li><strong>Ablauf innerhalb von Service Up:</strong>\n<ul class=\"fig-list\"><li>Eintritt über den Sub-Initialknoten in <code>Not Subscribed</code>.\n</li><li><code>Not Subscribed</code> -&gt; <code>Subscribed</code>: Bei <code>receive(SubscribeEventgroup)</code> wird <code>/enableEvents()</code> ausgeführt und <code>send(SubscribeEventgroupAck)</code> ausgelöst.\n</li><li>Selbstübergang an <code>Subscribed</code>: Bei erneutem <code>receive(SubscribeEventgroup)</code> (Erneuerung/weitere Subskription) erfolgt <code>/send(SubscribeEventgroupAck)</code>.\n</li><li><code>Subscribed</code> -&gt; <code>Not Subscribed</code>:\n<ul class=\"fig-list\"><li>Explizite Abmeldung über <code>receive(StopSubscribeEventgroup)</code> mit Aktion <code>/disableEvents()</code>.\n</li><li>Timeout-Ablauf über <code>TTL_expired</code> mit Guard <code>[SubscriptionCounter==1]</code> und Aktion <code>/disableEvents()</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindliches Zustandsdiagramm für SOME/IP-SD-Serverimplementierungen gemäß Spezifikationsanforderung (z. B. PRS_SOMEIPSD_00466).\n</li><li>Definiert das exakte Zusammenspiel zwischen Empfang von SD-Subskriptionsnachrichten, dem Senden positiver Quittungen (<code>SubscribeEventgroupAck</code>) und dem Schalten der Event-Übertragung.\n</li><li>Das BSW-Modul (z. B. <code>SoAd</code> / <code>Sd</code>) muss sicherstellen, dass bei der ersten Subskription das Event-Routing aktiviert (<code>enableTxRoutingGroup</code>) und bei Wegfall des letzten Abonnenten (<code>SubscriptionCounter==1</code> oder <code>StopSubscribeEventgroup</code>) deaktiviert wird (<code>disableTxRoutingGroup</code>).\n</li><li>Das Bereitstellen des Dienstes (<code>OfferService</code>) impliziert automatisch die Publikationsbereitschaft der zugehörigen Eventgroups (<code>PublishEventgroup</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0da6f8bc66ee9c0e", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm Service Discovery Eventgroup Pub/Sub (Unicast)</code>) im Kontext des AUTOSAR SOME/IP Service Discovery Protocols (SOME/IP-SD). Es modelliert das serverseitige Verhalten und den Lebenszyklus des Publish/Subscribe-Mechanismus für Unicast-Eventgroups (<code>Eventgroup_PubSub (Unicast Eventgroup)</code>) in Abhängigkeit vom übergeordneten Verfügbarkeitszustand des Services.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände / Composite States:</strong>\n<ul class=\"fig-list\"><li><code>Eventgroup_PubSub (Unicast Eventgroup)</code>: Haupt-Zustandsautomat mit Initialknoten.\n</li><li><code>Service Down</code>: Einfacher Zustand bei inaktivem bzw. nicht verfügbarem Service.\n</li><li><code>Service Up</code>: Zusammengesetzter Zustand (Composite State) mit eigenem Sub-Initialknoten und den Subzuständen <code>Not Subscribed</code> sowie <code>Subscribed</code>.\n</li></ul>\n</li><li><strong>Nachrichten &amp; Schnittstellen (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Empfangene Nachrichten: <code>SubscribeEventgroup</code>, <code>StopSubscribeEventgroup</code>.\n</li><li>Gesendete Nachrichten: <code>SubscribeEventgroupAck</code>.\n</li></ul>\n</li><li><strong>Interne Aktionen &amp; Routing-Steuerung:</strong>\n<ul class=\"fig-list\"><li><code>enableEvents()</code> (in AUTOSAR abgebildet auf <code>enableTxRoutingGroup</code>).\n</li><li><code>disableEvents()</code> (in AUTOSAR abgebildet auf <code>disableTxRoutingGroup</code>).\n</li></ul>\n</li><li><strong>Bedingungen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li>Guards: <code>[Service==Down]</code>, <code>[Service==Up]</code>, <code>[SubscriptionCounter==1]</code>.\n</li><li>Timer-Ereignis: <code>TTL_expired</code>.\n</li></ul>\n</li><li><strong>Kommentare / Notizen:</strong>\n<ul class=\"fig-list\"><li>Hinweis: „OfferService is implicit PublishEventgroup“.\n</li><li>Mapping-Notiz: „AUTOSAR: enableEvents = enableTxRoutingGroup, disableEvents = disableTxRoutingGroup“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Service-Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Vom initialen Pseudozustand erfolgt je nach Guard-Bedingung der Übergang nach <code>Service Down</code> (<code>[Service==Down]</code>) oder direkt in den Composite State <code>Service Up</code> (<code>[Service==Up]</code>).\n</li><li>Zwischen <code>Service Down</code> und <code>Service Up</code> schalten die Events <code>ServiceUp</code> bzw. <code>ServiceDown</code> um.\n</li></ul>\n</li><li><strong>Ablauf innerhalb von Service Up:</strong>\n<ul class=\"fig-list\"><li>Eintritt über den Sub-Initialknoten in <code>Not Subscribed</code>.\n</li><li><code>Not Subscribed</code> -&gt; <code>Subscribed</code>: Bei <code>receive(SubscribeEventgroup)</code> wird <code>/enableEvents()</code> ausgeführt und <code>send(SubscribeEventgroupAck)</code> ausgelöst.\n</li><li>Selbstübergang an <code>Subscribed</code>: Bei erneutem <code>receive(SubscribeEventgroup)</code> (Erneuerung/weitere Subskription) erfolgt <code>/send(SubscribeEventgroupAck)</code>.\n</li><li><code>Subscribed</code> -&gt; <code>Not Subscribed</code>:\n<ul class=\"fig-list\"><li>Explizite Abmeldung über <code>receive(StopSubscribeEventgroup)</code> mit Aktion <code>/disableEvents()</code>.\n</li><li>Timeout-Ablauf über <code>TTL_expired</code> mit Guard <code>[SubscriptionCounter==1]</code> und Aktion <code>/disableEvents()</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindliches Zustandsdiagramm für SOME/IP-SD-Serverimplementierungen gemäß Spezifikationsanforderung (z. B. PRS_SOMEIPSD_00466).\n</li><li>Definiert das exakte Zusammenspiel zwischen Empfang von SD-Subskriptionsnachrichten, dem Senden positiver Quittungen (<code>SubscribeEventgroupAck</code>) und dem Schalten der Event-Übertragung.\n</li><li>Das BSW-Modul (z. B. <code>SoAd</code> / <code>Sd</code>) muss sicherstellen, dass bei der ersten Subskription das Event-Routing aktiviert (<code>enableTxRoutingGroup</code>) und bei Wegfall des letzten Abonnenten (<code>SubscriptionCounter==1</code> oder <code>StopSubscribeEventgroup</code>) deaktiviert wird (<code>disableTxRoutingGroup</code>).\n</li><li>Das Bereitstellen des Dienstes (<code>OfferService</code>) impliziert automatisch die Publikationsbereitschaft der zugehörigen Eventgroups (<code>PublishEventgroup</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c2323bd9e2af75f0", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm Service Discovery Eventgroup Pub/Sub (Unicast)</code>) im Kontext des AUTOSAR SOME/IP Service Discovery Protocols (SOME/IP-SD). Es modelliert das serverseitige Verhalten und den Lebenszyklus des Publish/Subscribe-Mechanismus für Unicast-Eventgroups (<code>Eventgroup_PubSub (Unicast Eventgroup)</code>) in Abhängigkeit vom übergeordneten Verfügbarkeitszustand des Services.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände / Composite States:</strong>\n<ul class=\"fig-list\"><li><code>Eventgroup_PubSub (Unicast Eventgroup)</code>: Haupt-Zustandsautomat mit Initialknoten.\n</li><li><code>Service Down</code>: Einfacher Zustand bei inaktivem bzw. nicht verfügbarem Service.\n</li><li><code>Service Up</code>: Zusammengesetzter Zustand (Composite State) mit eigenem Sub-Initialknoten und den Subzuständen <code>Not Subscribed</code> sowie <code>Subscribed</code>.\n</li></ul>\n</li><li><strong>Nachrichten &amp; Schnittstellen (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Empfangene Nachrichten: <code>SubscribeEventgroup</code>, <code>StopSubscribeEventgroup</code>.\n</li><li>Gesendete Nachrichten: <code>SubscribeEventgroupAck</code>.\n</li></ul>\n</li><li><strong>Interne Aktionen &amp; Routing-Steuerung:</strong>\n<ul class=\"fig-list\"><li><code>enableEvents()</code> (in AUTOSAR abgebildet auf <code>enableTxRoutingGroup</code>).\n</li><li><code>disableEvents()</code> (in AUTOSAR abgebildet auf <code>disableTxRoutingGroup</code>).\n</li></ul>\n</li><li><strong>Bedingungen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li>Guards: <code>[Service==Down]</code>, <code>[Service==Up]</code>, <code>[SubscriptionCounter==1]</code>.\n</li><li>Timer-Ereignis: <code>TTL_expired</code>.\n</li></ul>\n</li><li><strong>Kommentare / Notizen:</strong>\n<ul class=\"fig-list\"><li>Hinweis: „OfferService is implicit PublishEventgroup“.\n</li><li>Mapping-Notiz: „AUTOSAR: enableEvents = enableTxRoutingGroup, disableEvents = disableTxRoutingGroup“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Service-Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Vom initialen Pseudozustand erfolgt je nach Guard-Bedingung der Übergang nach <code>Service Down</code> (<code>[Service==Down]</code>) oder direkt in den Composite State <code>Service Up</code> (<code>[Service==Up]</code>).\n</li><li>Zwischen <code>Service Down</code> und <code>Service Up</code> schalten die Events <code>ServiceUp</code> bzw. <code>ServiceDown</code> um.\n</li></ul>\n</li><li><strong>Ablauf innerhalb von Service Up:</strong>\n<ul class=\"fig-list\"><li>Eintritt über den Sub-Initialknoten in <code>Not Subscribed</code>.\n</li><li><code>Not Subscribed</code> -&gt; <code>Subscribed</code>: Bei <code>receive(SubscribeEventgroup)</code> wird <code>/enableEvents()</code> ausgeführt und <code>send(SubscribeEventgroupAck)</code> ausgelöst.\n</li><li>Selbstübergang an <code>Subscribed</code>: Bei erneutem <code>receive(SubscribeEventgroup)</code> (Erneuerung/weitere Subskription) erfolgt <code>/send(SubscribeEventgroupAck)</code>.\n</li><li><code>Subscribed</code> -&gt; <code>Not Subscribed</code>:\n<ul class=\"fig-list\"><li>Explizite Abmeldung über <code>receive(StopSubscribeEventgroup)</code> mit Aktion <code>/disableEvents()</code>.\n</li><li>Timeout-Ablauf über <code>TTL_expired</code> mit Guard <code>[SubscriptionCounter==1]</code> und Aktion <code>/disableEvents()</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindliches Zustandsdiagramm für SOME/IP-SD-Serverimplementierungen gemäß Spezifikationsanforderung (z. B. PRS_SOMEIPSD_00466).\n</li><li>Definiert das exakte Zusammenspiel zwischen Empfang von SD-Subskriptionsnachrichten, dem Senden positiver Quittungen (<code>SubscribeEventgroupAck</code>) und dem Schalten der Event-Übertragung.\n</li><li>Das BSW-Modul (z. B. <code>SoAd</code> / <code>Sd</code>) muss sicherstellen, dass bei der ersten Subskription das Event-Routing aktiviert (<code>enableTxRoutingGroup</code>) und bei Wegfall des letzten Abonnenten (<code>SubscriptionCounter==1</code> oder <code>StopSubscribeEventgroup</code>) deaktiviert wird (<code>disableTxRoutingGroup</code>).\n</li><li>Das Bereitstellen des Dienstes (<code>OfferService</code>) impliziert automatisch die Publikationsbereitschaft der zugehörigen Eventgroups (<code>PublishEventgroup</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6bc53f5772e2049f", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm Service Discovery Eventgroup Pub/Sub (Unicast)</code>) im Kontext des AUTOSAR SOME/IP Service Discovery Protocols (SOME/IP-SD). Es modelliert das serverseitige Verhalten und den Lebenszyklus des Publish/Subscribe-Mechanismus für Unicast-Eventgroups (<code>Eventgroup_PubSub (Unicast Eventgroup)</code>) in Abhängigkeit vom übergeordneten Verfügbarkeitszustand des Services.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände / Composite States:</strong>\n<ul class=\"fig-list\"><li><code>Eventgroup_PubSub (Unicast Eventgroup)</code>: Haupt-Zustandsautomat mit Initialknoten.\n</li><li><code>Service Down</code>: Einfacher Zustand bei inaktivem bzw. nicht verfügbarem Service.\n</li><li><code>Service Up</code>: Zusammengesetzter Zustand (Composite State) mit eigenem Sub-Initialknoten und den Subzuständen <code>Not Subscribed</code> sowie <code>Subscribed</code>.\n</li></ul>\n</li><li><strong>Nachrichten &amp; Schnittstellen (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Empfangene Nachrichten: <code>SubscribeEventgroup</code>, <code>StopSubscribeEventgroup</code>.\n</li><li>Gesendete Nachrichten: <code>SubscribeEventgroupAck</code>.\n</li></ul>\n</li><li><strong>Interne Aktionen &amp; Routing-Steuerung:</strong>\n<ul class=\"fig-list\"><li><code>enableEvents()</code> (in AUTOSAR abgebildet auf <code>enableTxRoutingGroup</code>).\n</li><li><code>disableEvents()</code> (in AUTOSAR abgebildet auf <code>disableTxRoutingGroup</code>).\n</li></ul>\n</li><li><strong>Bedingungen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li>Guards: <code>[Service==Down]</code>, <code>[Service==Up]</code>, <code>[SubscriptionCounter==1]</code>.\n</li><li>Timer-Ereignis: <code>TTL_expired</code>.\n</li></ul>\n</li><li><strong>Kommentare / Notizen:</strong>\n<ul class=\"fig-list\"><li>Hinweis: „OfferService is implicit PublishEventgroup“.\n</li><li>Mapping-Notiz: „AUTOSAR: enableEvents = enableTxRoutingGroup, disableEvents = disableTxRoutingGroup“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Service-Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Vom initialen Pseudozustand erfolgt je nach Guard-Bedingung der Übergang nach <code>Service Down</code> (<code>[Service==Down]</code>) oder direkt in den Composite State <code>Service Up</code> (<code>[Service==Up]</code>).\n</li><li>Zwischen <code>Service Down</code> und <code>Service Up</code> schalten die Events <code>ServiceUp</code> bzw. <code>ServiceDown</code> um.\n</li></ul>\n</li><li><strong>Ablauf innerhalb von Service Up:</strong>\n<ul class=\"fig-list\"><li>Eintritt über den Sub-Initialknoten in <code>Not Subscribed</code>.\n</li><li><code>Not Subscribed</code> -&gt; <code>Subscribed</code>: Bei <code>receive(SubscribeEventgroup)</code> wird <code>/enableEvents()</code> ausgeführt und <code>send(SubscribeEventgroupAck)</code> ausgelöst.\n</li><li>Selbstübergang an <code>Subscribed</code>: Bei erneutem <code>receive(SubscribeEventgroup)</code> (Erneuerung/weitere Subskription) erfolgt <code>/send(SubscribeEventgroupAck)</code>.\n</li><li><code>Subscribed</code> -&gt; <code>Not Subscribed</code>:\n<ul class=\"fig-list\"><li>Explizite Abmeldung über <code>receive(StopSubscribeEventgroup)</code> mit Aktion <code>/disableEvents()</code>.\n</li><li>Timeout-Ablauf über <code>TTL_expired</code> mit Guard <code>[SubscriptionCounter==1]</code> und Aktion <code>/disableEvents()</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ verbindliches Zustandsdiagramm für SOME/IP-SD-Serverimplementierungen gemäß Spezifikationsanforderung (z. B. PRS_SOMEIPSD_00466).\n</li><li>Definiert das exakte Zusammenspiel zwischen Empfang von SD-Subskriptionsnachrichten, dem Senden positiver Quittungen (<code>SubscribeEventgroupAck</code>) und dem Schalten der Event-Übertragung.\n</li><li>Das BSW-Modul (z. B. <code>SoAd</code> / <code>Sd</code>) muss sicherstellen, dass bei der ersten Subskription das Event-Routing aktiviert (<code>enableTxRoutingGroup</code>) und bei Wegfall des letzten Abonnenten (<code>SubscriptionCounter==1</code> oder <code>StopSubscribeEventgroup</code>) deaktiviert wird (<code>disableTxRoutingGroup</code>).\n</li><li>Das Bereitstellen des Dienstes (<code>OfferService</code>) impliziert automatisch die Publikationsbereitschaft der zugehörigen Eventgroups (<code>PublishEventgroup</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6abf7ba4a479d08a", "to": "FIG-641dbb8d7d0c16ee", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-641dbb8d7d0c16ee", "to": "FIG-6abf7ba4a479d08a", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6abf7ba4a479d08a", "to": "FIG-0da6f8bc66ee9c0e", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0da6f8bc66ee9c0e", "to": "FIG-c2323bd9e2af75f0", "fr": "R18-03_R1.4.0", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2323bd9e2af75f0", "to": "FIG-641dbb8d7d0c16ee", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-641dbb8d7d0c16ee", "to": "FIG-6bc53f5772e2049f", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
